[
  {
    "name": "device_act",
    "description": "Perform one closed tap, swipe, type, or hardware-button action on a phone device. There is no arbitrary shell.",
    "parameters": {
      "type": "object",
      "properties": {
        "deviceId": {
          "type": "string",
          "description": "Android serial or iOS UDID returned by device_list."
        },
        "action": {
          "oneOf": [
            {
              "type": "object",
              "additionalProperties": false,
              "properties": {
                "kind": {
                  "type": "string",
                  "const": "tap"
                },
                "x": {
                  "type": "integer",
                  "description": "Horizontal pixel coordinate."
                },
                "y": {
                  "type": "integer",
                  "description": "Vertical pixel coordinate."
                }
              },
              "required": [
                "kind",
                "x",
                "y"
              ]
            },
            {
              "type": "object",
              "additionalProperties": false,
              "properties": {
                "kind": {
                  "type": "string",
                  "const": "swipe"
                },
                "x1": {
                  "type": "integer",
                  "description": "Start horizontal pixel coordinate."
                },
                "y1": {
                  "type": "integer",
                  "description": "Start vertical pixel coordinate."
                },
                "x2": {
                  "type": "integer",
                  "description": "End horizontal pixel coordinate."
                },
                "y2": {
                  "type": "integer",
                  "description": "End vertical pixel coordinate."
                }
              },
              "required": [
                "kind",
                "x1",
                "y1",
                "x2",
                "y2"
              ]
            },
            {
              "type": "object",
              "additionalProperties": false,
              "properties": {
                "kind": {
                  "type": "string",
                  "const": "type"
                },
                "text": {
                  "type": "string",
                  "description": "Non-empty text to type."
                }
              },
              "required": [
                "kind",
                "text"
              ]
            },
            {
              "type": "object",
              "additionalProperties": false,
              "properties": {
                "kind": {
                  "type": "string",
                  "const": "button"
                },
                "name": {
                  "type": "string",
                  "description": "Hardware button to press.",
                  "enum": [
                    "home",
                    "back",
                    "recents",
                    "power",
                    "volume_up",
                    "volume_down"
                  ]
                }
              },
              "required": [
                "kind",
                "name"
              ]
            }
          ],
          "description": "Exactly one closed gesture or hardware-button action."
        }
      },
      "required": [
        "deviceId",
        "action"
      ]
    }
  }
]
